sys_script.script:
(function executeRule(current, previous) {

    if (current.getValue('queue') != 'input') {
        return;
    }

    var topic = current.getValue('topic') || '';

    if (
        topic != 'ONPAGE_TARGET_GROUPS' &&
        topic != 'ONPAGE_GROUPS' &&
        topic != 'ONPAGE_ACCOUNTS' &&
        topic != 'ONPAGE_CREATE_ACCOUNT' &&
        topic != 'ONPAGE_REGISTER'
    ) {
        return;
    }

    try {

        var onpage = new x_onpr_onpage.sync();

        var payload = current.getValue('payload');
        if (!payload) {
            throw new Error('ECC response payload is empty.');
        }

        var xml = new XMLDocument2();
        xml.parseXML(payload);

        var statusNode = xml.getNode('//parameters/parameter[@name="http_status_code"]');
        var status = statusNode ? statusNode.getAttribute('value') : '';

        var outputNode = xml.getNode('//result/output');
        var body = outputNode ? outputNode.getTextContent() : '';

        if (!status) {
            throw new Error('HTTP status code not found in ECC response.');
        }

        if (topic == 'ONPAGE_REGISTER') {
            var registerRoot = xml.getDocumentElement();
            var registerError = registerRoot ? registerRoot.getAttribute('error') : '';
            var setupObj = new x_onpr_onpage.setup();
            var registrationSuccess = setupObj.processRegistrationResponse(status, body, registerError);
            if (registrationSuccess) {
                gs.info('OnPage registration response processed successfully.');
            } else {
                gs.error('OnPage registration response processing failed.');
            }
            return;
        }

        if (status != '200') {
            var rootNode = xml.getDocumentElement();
            var errorMessage = rootNode ? rootNode.getAttribute('error') : '';
            onpage._handleErrors('', status, body || errorMessage);
            if (topic == 'ONPAGE_TARGET_GROUPS') {
                onpage.syncUsers();
            }
            return;
        }

        if (!body) {
            throw new Error('HTTP 200 response has an empty body.');
        }

        if (topic == 'ONPAGE_TARGET_GROUPS' || topic == 'ONPAGE_GROUPS') {
            onpage.processGroupsResponse(body);
            if (topic == 'ONPAGE_TARGET_GROUPS') {
                onpage.syncUsers();
            }
            return;
        }

        if (topic == 'ONPAGE_ACCOUNTS') {
            onpage.processAccountsResponse(body);
            return;
        }

        if (topic == 'ONPAGE_CREATE_ACCOUNT') {
            onpage.processCreateAccountResponse(body);
            return;
        }

    } catch (ex) {
        gs.error('OnPage ECC response processing failed. Topic: ' + topic + ' | Error: ' + ex.message);
    }

})(current, previous);
